    fn workspace_root() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .ancestors()
            .nth(2)
            .expect("workspace root")
            .to_path_buf()
    }

    fn assert_snapshot_tail(snapshot: &[RuntimeValue], expected: &[RuntimeValue]) {
        assert!(
            snapshot.len() >= expected.len(),
            "snapshot shorter than expected tail: snapshot={snapshot:?} expected={expected:?}"
        );
        assert_eq!(
            &snapshot[snapshot.len() - expected.len()..],
            expected,
            "snapshot tail mismatch: snapshot={snapshot:?}"
        );
    }

    #[test]
    fn source_snapshot_uses_entry_procedure_slots_when_helper_precedes_main_vm_and_jit() {
        let source = "Private Function MakeBuf() As Byte()\n\
Dim buf() As Byte\n\
ReDim buf(2)\n\
buf(0) = 90\n\
buf(1) = 91\n\
buf(2) = 92\n\
MakeBuf = buf\n\
End Function\n\
\n\
Sub Main()\n\
Dim result() As Byte\n\
Dim x0 As Long\n\
Dim x1 As Long\n\
Dim x2 As Long\n\
result = MakeBuf()\n\
x0 = result(0)\n\
x1 = result(1)\n\
x2 = result(2)\n\
End Sub";
        for enable_jit in [false, true] {
            let engine = Engine::new(HostConfig {
                enable_jit,
                root_object_name: None,
            });
            let snapshot = engine
                .execute_source_with_value_snapshot(source)
                .expect("source snapshot should execute");
            assert_eq!(snapshot.len(), 4);
            assert!(
                matches!(snapshot[0], RuntimeValue::ArrayIntent(_)),
                "result should remain a runtime array carrier for enable_jit={enable_jit}; snapshot={snapshot:?}"
            );
            assert_eq!(
                &snapshot[1..],
                &[
                    RuntimeValue::I32(90),
                    RuntimeValue::I32(91),
                    RuntimeValue::I32(92),
                ],
                "snapshot should reflect Main scalar slots for enable_jit={enable_jit}"
            );
        }
    }

    struct ProjectAwareCallbacks {
        mutations: Mutex<Vec<String>>,
    }

    impl HostCallbacks for ProjectAwareCallbacks {
        fn on_msg_box(&self, _prompt: &str, style: i32) -> i32 {
            style.max(1)
        }

        fn on_input_box(&self, _prompt: &str, default: &str) -> String {
            default.to_string()
        }

        fn on_status_bar(&self, _text: &str) {}

        fn on_debug_print(&self, _text: &str) {}

        fn supports_project_catalog(&self) -> bool {
            true
        }

        fn supports_project_references(&self) -> bool {
            true
        }

        fn supports_project_mutation(&self) -> bool {
            true
        }

        fn on_list_projects(&self) -> ProjectCallbackResult<Vec<ProjectDescriptor>> {
            Ok(vec![ProjectDescriptor {
                project_name: "Workbook".to_string(),
                kind: ProjectDescriptorKind::Host,
                supports_extension_modules: true,
            }])
        }

        fn on_get_project(&self, project_name: &str) -> ProjectCallbackResult<ProjectDescriptor> {
            Ok(ProjectDescriptor {
                project_name: project_name.to_string(),
                kind: ProjectDescriptorKind::Host,
                supports_extension_modules: true,
            })
        }

        fn on_list_project_references(
            &self,
            project_name: &str,
        ) -> ProjectCallbackResult<Vec<ProjectReferenceDescriptor>> {
            Ok(vec![ProjectReferenceDescriptor {
                project_name: project_name.to_string(),
                referenced_name: "HostExt".to_string(),
                kind: ProjectReferenceKind::Project,
            }])
        }

        fn on_attach_host_extension_module(
            &self,
            change: &HostExtensionModuleChange,
        ) -> ProjectCallbackResult<()> {
            self.mutations
                .lock()
                .expect("mutation log lock")
                .push(format!("{}::{}", change.project_name, change.module_name));
            Ok(())
        }
    }

    #[cfg(target_os = "windows")]
    fn create_controlled_com_object(engine: &Engine) -> oxvba_runtime::ObjectHandle {
        match engine
            .host_services
            .com()
            .create_object(RuntimeValue::String(BStr("OxVba.TestDispatch".to_string())))
            .expect("create_object should return controlled COM object")
        {
            RuntimeValue::ObjectHandle(handle) => handle,
            other => panic!("expected object handle from create_object, got {:?}", other),
        }
    }

    #[test]
    fn engine_rebuilds_preserve_callback_backed_project_services() {
        let callbacks = Arc::new(ProjectAwareCallbacks {
            mutations: Mutex::new(Vec::new()),
        });
        let mut engine = Engine::new(HostConfig::default());
        engine.set_host_policy(HostPolicy::interactive_dev());
        engine.set_host_callbacks(Some(callbacks.clone()));

        let projects = engine
            .host_services
            .project_catalog()
            .expect("project catalog should be exposed")
            .list_projects()
            .expect("project list should succeed");
        assert_eq!(projects[0].project_name, "Workbook");

        engine.set_unsupported_feature_mode(UnsupportedFeatureMode::Runtime);

        let references = engine
            .host_services
            .project_references()
            .expect("project references should be exposed after rebuild")
            .list_references("Workbook")
            .expect("reference list should succeed after rebuild");
        assert_eq!(references[0].referenced_name, "HostExt");

        engine
            .host_services
            .project_mutation()
            .expect("project mutation should be exposed after rebuild")
            .attach_host_extension_module(&HostExtensionModuleChange {
                project_name: "Workbook".to_string(),
                module_name: "HostExt".to_string(),
                source: "Public Sub Sync()\nEnd Sub".to_string(),
            })
            .expect("host extension attach should succeed");

        assert_eq!(
            callbacks
                .mutations
                .lock()
                .expect("mutation log lock")
                .as_slice(),
            ["Workbook::HostExt"]
        );
    }

    #[cfg(target_os = "windows")]
    fn dispatch_controlled_com_call(
        engine: &Engine,
        object: oxvba_runtime::ObjectHandle,
        member: i32,
        arg: i32,
    ) -> RuntimeValue {
        let request = ComInvokeRequest::new(
            object,
            member.into(),
            if arg == oxvba_com::DISPATCH_INVOKE_MISSING_ARG_TOKEN {
                Vec::new()
            } else {
                vec![ComInvokeArg::positional(arg)]
            },
        );
        engine
            .host_services
            .com()
            .dispatch_invoke_runtime_value_v2(&request)
            .expect("dispatch_invoke should succeed")
    }

    fn repo_path(relative: &str) -> PathBuf {
        workspace_root().join(relative)
    }

    fn divergence_record_has_required_sections(record_path: &Path) -> bool {
        let Ok(text) = std::fs::read_to_string(record_path) else {
            return false;
        };
        if !text.starts_with("# DIV-") {
            return false;
        }
        let required = [
            "- Scope impact:",
            "- Fixture:",
            "- Reproduction command:",
            "- Tracking status:",
        ];
        required.iter().all(|label| text.contains(label))
    }

    #[test]
    fn execute_source_with_default_vm_path() {
        let mut engine = Engine::new(HostConfig {
            enable_jit: false,
            root_object_name: Some("Application".to_string()),
        });
        engine.register_root_object("Application", "Host.Application");
        assert!(engine.has_root_object("Application"));

        let result = engine.execute_source("Sub Main()\nEnd Sub");
        assert!(result.is_ok());
    }

